//! Formatter tests.
//!
//! Each `.rb` file under `tests/fixtures/format/` must already be
//! formatted. Two checks per fixture:
//!   1. Stability:   format(input) == input
//!   2. Idempotency: format(format(input)) == format(input)

use std::fs;
use std::path::Path;

/// Checks the fixture `tests/fixtures/format/<name>.rb`; the tests that
/// call it are generated by `build.rs`, one per file.
fn check_fixture(name: &str) {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/format")
        .join(format!("{name}.rb"));
    let input = fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("failed to read {}: {e}", path.display()));

    let output = tuxedo::format(&input).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    assert_eq!(
        input,
        output,
        "fixture is not already formatted: {}",
        path.display()
    );

    let reformatted = tuxedo::format(&output).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    assert_eq!(
        output,
        reformatted,
        "formatting is not idempotent for fixture: {}",
        path.display()
    );
}

include!(concat!(env!("OUT_DIR"), "/format_fixtures.rs"));
